package mock

import (
	"encoding/hex"

	"github.com/xssnick/tonutils-go/tlb"
	"github.com/xssnick/tonutils-go/tvm/cell"
)

type rawTx struct {
	Data string
	Fee  uint64
	Skip bool
}

var RawTxs = []rawTx{
	{
		Data: "",
		Fee:  3031086,
	},
	{
		Data: "",
		Fee:  2551847,
	},
	{
		Data: "",
		Fee:  1988534,
	},
	{
		// Type: tlb.TickTock{} -> ignore
		Data: "",
		Fee:  0,
		Skip: true,
	},
	{
		// Bounce: true -> ignore
		Data: "",
		Fee:  2495998,
		Skip: true,
	},
}

func GetTxs() ([]tlb.Transaction, error) {
	var txs []tlb.Transaction

	for _, raw := range RawTxs {
		data, err := hex.DecodeString(raw.Data)
		if err != nil {
			return nil, err
		}

		var c *cell.Cell
		c, err = cell.FromBOC(data)
		if err != nil {
			return nil, err
		}

		slice := c.BeginParse()
		var tx tlb.Transaction
		err = tlb.LoadFromCell(&tx, slice)
		if err != nil {
			return nil, err
		}

		// recompute hash
		c, err = tlb.ToCell(tx)
		if err != nil {
			return nil, err
		}

		tx.Hash = c.Hash()[:]
		tx.TotalFees = tlb.CurrencyCollection{
			Coins: tlb.FromNanoTONU(raw.Fee),
		}

		txs = append(txs, tx)
	}

	return txs, nil
}
